const KEY='benchwork-onboarding-v1';
let s={employee:'',coordinator:'',checks:{},events:[],arrival:{},signatures:{}};
try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&v.checks&&v.events&&v.arrival&&v.signatures)s=v}catch{}
const $=id=>document.getElementById(id),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(s))}catch{toast('Browser storage is unavailable. Export your record to keep it.')}}
function stamp(){return new Date().toLocaleString(undefined,{timeZoneName:'short'})+' · '+Intl.DateTimeFormat().resolvedOptions().timeZone}
function log(text){s.events.push({text,time:stamp()});save();render()}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4500)}
function gates(){const offer=['option','employer','datefield'].every(k=>s.checks[k]);const contract=s.checks.receipt&&s.checks.offerSent&&offer;const email=contract&&s.checks.contractSent&&s.checks.employeeOption&&s.checks.employerOption;return{offer,contract,email}}
function check(k,text,disabled=false){return `<label class="check"><input type="checkbox" data-check="${k}" ${s.checks[k]?'checked':''} ${disabled?'disabled':''}>${text}</label>`}
function sign(key,label,enabled){const sig=s.signatures[key];return `<div class="signature"><label>${label}${sig?`<strong> · ${escape(sig.name)}</strong>`:`<input id="sig-${key}" placeholder="Type full name" ${!enabled?'disabled':''}>`}</label>${sig?`<small>Signed ${escape(sig.time)}<br>Recorded date is fixed.</small>`:`<button data-sign="${key}" ${!enabled?'disabled':''}>${key==='offer'?'Sign & record Date':'Apply signature'}</button>`}</div>`}
function card(n,title,sub,status,body){return `<section class="stage"><div class="stage-head"><span class="number">${n}</span><div><h2>${title}</h2><div class="subtitle">${sub}</div></div><span class="badge ${status==='Complete'?'done':''}">${status}</span></div><div class="body">${body}</div></section>`}
function render(){const g=gates();let stages=Number(!!s.checks.receipt)+Number(!!s.checks.contractSent)+Number(!!s.checks.emailSent);$('count').textContent=`${stages} of 3 stages complete`;$('progress').style.width=(stages/3*100)+'%';
 $('stages').innerHTML=card('01','Offer letter','Prepare the offer, then confirm employee receipt.',s.checks.receipt?'Complete':'In progress',
 check('option','Employee e-signature option is included.',!!s.checks.offerSent)+check('employer',"Employer’s signature is attached before sending.",!!s.checks.offerSent)+check('datefield','Clickable Date field records and retains the signing date, time, and time zone.',!!s.checks.offerSent)+`<div class="action-row"><button data-action="offerSent" ${!g.offer||s.checks.offerSent?'disabled':''}>${s.checks.offerSent?'✓ Offer sent':'Confirm offer sent'}</button><small>Confirm only after sending the prepared offer.</small></div>`+
 sign('offer','Employee e-signature',!!s.checks.offerSent)+check('receipt','Employee receipt of the offer letter is confirmed.',!s.checks.offerSent||!!s.checks.contractSent))+
 card('02','Employment contract','Available after confirmed offer receipt.',s.checks.contractSent?'Complete':g.contract?'Ready':'Locked',
 check('employeeOption','Employee e-signature option is included.',!g.contract||!!s.checks.contractSent)+check('employerOption','Employer e-signature option is included.',!g.contract||!!s.checks.contractSent)+`<div class="action-row"><button data-action="contractSent" ${!g.contract||!s.checks.employeeOption||!s.checks.employerOption||s.checks.contractSent?'disabled':''}>${s.checks.contractSent?'✓ Contract sent':'Confirm contract sent'}</button><small>${g.contract?'Confirm after sending the contract.':'Waiting for offer preparation and confirmed receipt.'}</small></div>`+sign('contractEmployee','Employee signature',!!s.checks.contractSent)+sign('contractEmployer','Employer signature',!!s.checks.contractSent))+
 card('03','Onboarding email','Give your new teammate a confident first day.',s.checks.emailSent?'Complete':g.email?'Ready':'Locked',
 `<div class="fields"><label>FIRST-DAY DATE<input type="date" data-arrival="date" value="${escape(s.arrival.date)}" ${s.checks.emailSent?'disabled':''}></label><label>ARRIVAL TIME<input type="time" data-arrival="time" value="${escape(s.arrival.time)}" ${s.checks.emailSent?'disabled':''}></label><label class="wide">TIME ZONE<input data-arrival="zone" placeholder="e.g. America/Vancouver" value="${escape(s.arrival.zone)}" ${s.checks.emailSent?'disabled':''}></label><label class="wide">REPORTING ADDRESS<textarea data-arrival="address" placeholder="Street, city, region, postal code" ${s.checks.emailSent?'disabled':''}>${escape(s.arrival.address)}</textarea></label></div><div class="action-row"><button id="preview" class="secondary">Preview email</button><button id="email-confirm" data-action="emailSent" ${!emailReady()||s.checks.emailSent?'disabled':''}>${s.checks.emailSent?'✓ Email sent':'Confirm email sent'}</button><small>${g.email?'All arrival details are required.':'Waiting for the employment contract to be sent.'}</small></div><div id="email-preview" hidden></div>`);
 $('events-count').textContent=s.events.length;$('events').innerHTML=s.events.length?s.events.slice().reverse().map(e=>`<div class="event">${escape(e.text)}<small>${escape(e.time)}</small></div>`).join(''):'<p>No activity yet.<br>Every confirmed milestone appears here.</p>';
}
function emailReady(){return gates().email&&['date','time','zone','address'].every(k=>s.arrival[k]?.trim())}
for(const k of ['employee','coordinator']){$(k).value=s[k];$(k).addEventListener('input',e=>{s[k]=e.target.value;save()})}
$('stages').addEventListener('change',e=>{const k=e.target.dataset.check;if(!k)return;const g=gates();if((['option','employer','datefield'].includes(k)&&s.checks.offerSent)||(k==='receipt'&&(!s.checks.offerSent||s.checks.contractSent))||(['employeeOption','employerOption'].includes(k)&&(!g.contract||s.checks.contractSent))){render();return}s.checks[k]=e.target.checked;log(`${e.target.checked?'Confirmed':'Unconfirmed'}: ${e.target.parentElement.textContent.trim()}`)});
$('stages').addEventListener('input',e=>{const k=e.target.dataset.arrival;if(!k||s.checks.emailSent)return;s.arrival[k]=e.target.value;save();$('email-confirm').disabled=!emailReady()});
$('stages').addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn||btn.disabled)return;const action=btn.dataset.action;if(action){const g=gates();if((action==='offerSent'&&!g.offer)||(action==='contractSent'&&(!g.contract||!s.checks.employeeOption||!s.checks.employerOption))||(action==='emailSent'&&!emailReady()))return;if(!s.employee.trim()||!s.coordinator.trim()){toast('Add the employee and HR coordinator names first.');return}const label={offerSent:'Offer letter sent',contractSent:'Employment contract sent',emailSent:'Onboarding email sent'}[action];if(!confirm(`Confirm: ${label.toLowerCase()} to ${s.employee}? Only confirm if this action has already occurred.`))return;s.checks[action]=true;log(label);toast('Confirmed and added to the activity log.')}const key=btn.dataset.sign;if(key){if(s.signatures[key]||!(key==='offer'?s.checks.offerSent:s.checks.contractSent))return;const name=$('sig-'+key).value.trim();if(!name){toast('Enter the signer’s full name.');return}if(!confirm('Apply this typed signature and record the current date and time? This is a browser-local record.'))return;s.signatures[key]={name,time:stamp(),iso:new Date().toISOString()};log(`${key==='offer'?'Offer letter':key==='contractEmployee'?'Contract employee':'Contract employer'} signature recorded`)}if(btn.id==='preview'){const p=$('email-preview');p.hidden=!p.hidden;p.innerHTML=`<p><b>Subject: Your first day — welcome aboard!</b></p><p>Hello ${escape(s.employee||'[Employee]')},<br>We look forward to welcoming you on ${escape(s.arrival.date||'[Date]')} at ${escape(s.arrival.time||'[Time]')} (${escape(s.arrival.zone||'[Time zone]')}).<br>Please report to ${escape(s.arrival.address||'[Full address]')}.<br>See you soon,<br>${escape(s.coordinator||'[HR coordinator]')}</p>`}});
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='benchwork-onboarding-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
render();
